    \label{def:sub}
    For any set $S \subseteq T \subseteq V$ and $x \in V \setminus T$, a set function $f:2^V \rightarrow \mathbb{R}^{\geq 0}$ is submodular if
    \begin{equation}
\label{eq:marginal-gain}
    f(S \cup \{x\})-f(S)\geq f(T \cup \{x\})-f(T).
\end{equation}

\begin{equation}
\label{eq:marginal-gain}
    f(S \cup \{x\})-f(S)\geq f(T \cup \{x\})-f(T).
\end{equation}

\label{def:weak-sub}
    A set function $f:2^V \rightarrow \mathbb{R}^{\geq 0}$ is $\gamma$-weakly submodular if for every set $S \subseteq T \subseteq V$:
    \begin{equation}
    \label{eq:weak-submodularity}
        \sum\nolimits_{u\in T \setminus S} f(u \mid S)  \geq  \gamma \big(f(T)-f(S)\big).
    \end{equation}
    $\gamma \in (0,1]$ is referred to as the submodularity ratio and $f$ is submodular iff $\gamma=1$.

\begin{equation}
        \label{eq:weak-submodularity}
            \sum\nolimits_{u\in T \setminus S} f(u \mid S)  \geq  \gamma \big(f(T)-f(S)\big).
        \end{equation}

\label{def:approximate}
A set function $\Tilde{f}$ is $\delta$-approximate to the utility function $f$ if for every $S \subseteq V$,
    \[  |f(S) - \Tilde{f}(S) | \leq \delta \]

   \caption{\textsc{UP}($f, c, \gamma, \epsilon$)}
   \label{alg:up}
\begin{algorithmic}[1]
   \STATE {\bfseries Input:} utility function $f$, cost function $c$, submodularity ratio $\gamma$, error threshold $\epsilon$.
   \STATE {\bfseries Output:} $\Tilde{S} = arg\,max_{S_i, i \in [n]} f(S_i)-c(S_i)$.
   \STATE $S_0 \gets \emptyset$; $i\gets 1$
    \STATE $u(e) \gets 0$ for all $e \in V$ 
    \STATE $PQ \gets$ priority\_queue$(\{(\frac{f(e)}{c(e)}, e) \mid e \in V\})$
    \WHILE{True}
    \STATE Remove entries from $PQ$ where the density(key) $\leq \gamma$
        \IF{PQ is empty}
            \STATE \textsc{Terminate the Algorithm}  
        \ENDIF
        \STATE $(\tau_i, v_i) \gets PQ.getTopAndRemove()$ 
        \STATE $u(v_i)++$ 
        \IF{$\frac{f(v_i|S_{i-1})}{c(v_i)} \geq \max\{\gamma, (1-\epsilon)\tau_i \}$}
            \STATE $S_i \gets S_{i-1} \cup \{v_i\}$
            \STATE $i++$
            \STATE \textsc{Continue to the Next Iteration} 
        \ENDIF
        \IF{$u(v_i) \leq \frac{\log \frac{n}{\gamma \epsilon}}{\epsilon}$}
            \STATE $PQ.push((\frac{f(v_i|S_{i-1})}{c(v_i)}, v_i)$) 
        \ENDIF    
    \ENDWHILE
\end{algorithmic}


